// faperejil — guion FUENTE del vlog continuo. Cada línea = 1 tramo = 1 clip.
// k: h = Federer habla a cámara (su voz del máster) · d = plano de detalle (keyframe, sin habla; su voz por encima)
//    w = Carmen habla (SIN audio ref; en el armado suena el audio propio del clip; NO va al máster)
// t: lo que se dice · a: qué pasa durante el clip (EN) · e: estado FINAL = ancla siguiente (EN)
// d: da/db = primer y último cuadro del primer plano (EN); e = cómo queda la escena ancha al volver.
export const SCENES = [
{ id: "S1", lugar: "patio con macetas", base: "patio",
  k0: "A small sunny back patio of a modest family house in the morning: terracotta pots with herbs along a whitewashed wall, one BIG clay pot full of bright green flat-leaf parsley in the foreground on a low wooden bench, a watering can, a folded garden glove, a pair of kitchen scissors on the bench, a plastic chair, laundry line in the back, a glass door to the kitchen on the right. The doctor crouches beside the parsley pot, one hand touching the leaves, looking at the viewer mid-sentence, friendly. Medium-wide shot from about two meters, eye level with him, whole pot and his upper body in frame, room around him.",
  lines: [
  { id: "s1_01", k: "h", t: "Mira esto. Es perejil, del común, del que te regalan en la verdulería. Y te voy a contar algo que me dijo una paciente de setenta años.",
    a: "He touches the parsley leaves and lifts a few stems toward the viewer while he talks, then looks back up at the viewer.",
    e: "Same patio, a few seconds later: he is still crouching by the parsley pot, now holding up a few long parsley stems between two fingers toward the viewer, eyebrows raised, about to tell a story." },
  { id: "s1_02", k: "h", t: "Me dijo: doctor, yo no quiero verme linda. Quiero que cuando digo mi edad no me pongan esa cara. Ya sabes cuál cara.",
    a: "He lets go of the stems, rests his forearms on his knees and imitates a doubtful look with a small wry smile, then shrugs.",
    e: "Same patio: he is crouching with forearms on his knees, a knowing half-smile and one eyebrow raised at the viewer." },
  { id: "s1_03", k: "d", t: "Y te digo lo mismo que a ella, derecho. El perejil no borra una arruga profunda. No fabrica colágeno por arte de magia.",
    a: "Close-up of his hands: the kitchen scissors cut a handful of parsley stems near the soil, slowly, stem by stem, and the left hand gathers them into a bunch.",
    da: "Close-up shot of the big clay pot of flat-leaf parsley on the wooden bench: his left hand holds a group of stems, his right hand holds the kitchen scissors open around them near the soil. Only his hands and forearms (blue scrub sleeves pushed up, black smartwatch) are visible, no face.",
    db: "Same close-up a few seconds later: his left hand now holds a generous cut bunch of parsley, the scissors closed in the right hand, some cut stubs visible in the pot.",
    e: "Same patio, wide as before: he is now standing next to the parsley pot holding a generous bunch of cut parsley in his left hand and the scissors in his right, looking at the viewer, serious and sincere." },
  { id: "s1_04", k: "h", t: "Pero sí hace otra cosa, que se nota en el espejo en unas semanas. Y te la doy completa ahora mismo, no al final.",
    a: "Standing, he holds up the bunch of parsley toward the viewer, nods, then points at the kitchen door with the scissors.",
    e: "Same patio: he stands holding up the bunch of parsley toward the viewer with a small confident smile, the other hand pointing at the glass kitchen door." },
  { id: "s1_05", k: "h", t: "Corto un buen puñado, este, y nos vamos a la cocina.",
    a: "He shakes the bunch lightly, puts the scissors on the bench and starts walking toward the glass kitchen door, turning his head to the viewer.",
    e: "Same patio: he has walked to the glass kitchen door on the right, one hand on the handle, the parsley bunch in the other hand, looking back over his shoulder at the viewer with a smile." },
]},

{ id: "S2", lugar: "cocina (receta)", base: "kitchen",
  k0: "Same photo, but: the book and the aloe leaves are gone from the counter. On the counter in front of him now: a big fresh bunch of flat-leaf parsley, a wooden cutting board with a kitchen knife, a clean empty glass jar with a metal lid, a white electric kettle, a tall heat-proof glass measuring jug, a small fine-mesh strainer and a small white saucer. He rests both hands on the counter beside the parsley, looking at the viewer mid-sentence, friendly. Keep the same kitchen, same window, same shelf, same framing (waist up behind the counter, room around him).",
  lines: [
  { id: "s2_01", k: "h", t: "Bueno, aquí estamos. Todo lo que necesitas: el perejil, agua y un frasco de vidrio limpio. Nada más, de verdad.",
    a: "He points one by one at the parsley bunch, the kettle and the empty glass jar on the counter while he names them, then opens his hands.",
    e: "Same kitchen: he holds the empty clean glass jar up at chest height with one hand, showing it to the viewer, the other hand open, a small smile." },
  { id: "s2_02", k: "d", t: "Lo lavas bien bajo el chorro de agua fría. Que no quede nada de tierra, sobre todo en los tallos.",
    a: "Close-up at the kitchen sink: his hands rinse the parsley bunch under a thin stream of cold tap water, turning it and rubbing the stems with the thumb.",
    da: "Close-up at the white kitchen sink by the window: his two hands hold the bunch of flat-leaf parsley under the black faucet, a thin stream of water starting to fall on the leaves. Only hands and forearms visible (blue scrub sleeves pushed up, black smartwatch).",
    db: "Same close-up a few seconds later: the parsley is wet and shiny, water dripping from the leaves, his thumb rubbing the stems under the stream.",
    e: "Same kitchen, wide as before behind the counter: he holds the wet, freshly washed parsley bunch over the cutting board, a few drops falling, looking at the viewer." },
  { id: "s2_03", k: "h", t: "Y la cantidad, que es lo que siempre me preguntan: un puñado, unos veinte gramos. Una taza de hojas sin apretar.",
    a: "He shakes the wet parsley gently over the board, then shows a loose handful in his cupped hand toward the viewer to show the size.",
    e: "Same kitchen: he holds a loose handful of parsley leaves in his cupped right hand toward the viewer to show the amount, the rest of the bunch on the board." },
  { id: "s2_04", k: "d", t: "Lo picas grueso, con hojas y tallitos finos. No hace falta que quede prolijo.",
    a: "Close-up: the knife chops the parsley coarsely on the wooden board with a steady rocking motion, the left hand's fingertips curled back.",
    da: "Close-up of the wooden cutting board on the white marble counter: a handful of washed flat-leaf parsley, his left hand holding it with fingertips curled, his right hand holding the kitchen knife on it, about to chop. Only hands visible.",
    db: "Same close-up a few seconds later: the parsley is now coarsely chopped in a small green pile on the board, the knife resting beside it.",
    e: "Same kitchen, wide: the coarsely chopped parsley is now inside the tall glass measuring jug on the counter; he holds the white electric kettle by the handle next to it, looking at the viewer." },
  { id: "s2_05", k: "h", t: "Ahora, doscientos cincuenta mililitros de agua recién hervida, una taza. La echas encima, así.",
    a: "He lifts the kettle and slowly pours steaming water over the chopped parsley in the glass jug, watching the level, then looks at the viewer.",
    e: "Same kitchen: the glass jug is filled to about one cup with hot water, chopped parsley floating, a little steam; he puts the kettle down and holds the small white saucer." },
  { id: "s2_06", k: "h", t: "Y lo tapas con un platito. Diez minutos. Ojo, no lo hiervas con el perejil adentro, eh, se echa a perder.",
    a: "He places the saucer on top of the jug as a lid, raises a finger in warning while he talks and shakes his head slightly.",
    e: "Same kitchen: the glass jug is covered with the white saucer; he leans on the counter with one index finger raised in a gentle warning, serious face." },
  { id: "s2_07", k: "d", t: "Después lo cuelas, y te queda esto, un agua verde clarita.",
    a: "Close-up: his hands pour the pale green parsley infusion from the glass jug through the fine-mesh strainer into the clean glass jar; the chopped leaves stay in the strainer.",
    da: "Close-up on the counter: his hand holds the fine-mesh strainer over the mouth of the empty clean glass jar, the other hand tilting the glass jug with the parsley infusion toward it. Only hands visible.",
    db: "Same close-up a few seconds later: the glass jar is now full of a clear light-green liquid, the soaked chopped parsley sitting in the strainer.",
    e: "Same kitchen, wide: he holds the glass jar full of clear light-green parsley water up in front of the window light, looking at it and then at the viewer, pleased." },
  { id: "s2_08", k: "h", t: "Lo dejas enfriar del todo y a la nevera, en el frasco bien tapado. Dura tres días. No más de tres.",
    a: "He screws the metal lid onto the jar, holds up three fingers toward the viewer, then walks two steps to the fridge and opens it.",
    e: "Same kitchen: he stands at the open white fridge at the side of the kitchen placing the closed glass jar of green parsley water on a shelf next to a milk carton, looking at the viewer." },
  { id: "s2_09", k: "h", t: "Eso es todo. Perejil, agua recién hervida, diez minutos tapado, colar, enfriar. Esa es la receta.",
    a: "He closes the fridge, comes back behind the counter and counts the steps on his fingers while he talks, calm.",
    e: "Same kitchen, back behind the counter as in the first shot: he counts on his fingers, showing four fingers to the viewer, relaxed smile." },
  { id: "s2_10", k: "h", t: "¿Y por qué funciona? El perejil tiene mucha vitamina C. Y la piel usa la vitamina C para fabricar su propio colágeno.",
    a: "He picks up one parsley sprig from the board and twirls it between his fingers while explaining, looking at the viewer.",
    e: "Same kitchen: he holds a single parsley sprig up between thumb and index finger, explaining, eyebrows slightly raised." },
  { id: "s2_11", k: "h", t: "O sea, no le pones colágeno a la cara. Le das una herramienta que ella usa para hacerlo. Es distinto, y quiero que lo sepas.",
    a: "He puts the sprig down, taps his own cheek lightly with two fingers and then opens his hand toward the viewer, sincere.",
    e: "Same kitchen: he rests both hands on the counter, leaning slightly toward the viewer, sincere direct look." },
  { id: "s2_12", k: "h", t: "Tiene también clorofila y antioxidantes, que ayudan a que la piel se vea más descansada. Más luminosa, digamos.",
    a: "He gestures with one open hand near his face, searching for the word, then smiles as he finds it.",
    e: "Same kitchen: his open hand is near his own cheek, a warm smile, looking at the viewer." },
  { id: "s2_12b", k: "h", t: "Y te digo por qué a esta edad se nota tanto. Después de los cincuenta, el colágeno se rompe más rápido de lo que se fabrica.",
    a: "He wipes his hands on a kitchen towel and leans on the counter, explaining calmly to the viewer.",
    e: "Same kitchen: he leans on the counter with the kitchen towel over his shoulder, explaining calmly." },
  { id: "s2_12c", k: "h", t: "Imagínate un andamio debajo de la piel. Con los años el andamio se afloja, y la piel de arriba se ve más fina, más seca.",
    a: "He interlocks the fingers of both hands like a scaffold in front of him, then lets them loosen and droop slowly.",
    e: "Same kitchen: his interlocked fingers are loosened and drooping in front of his chest, a thoughtful face." },
  { id: "s2_12d", k: "h", t: "Y además la piel produce menos grasa, se reseca. Y una piel seca marca mucho más cada arruga. Mucho más.",
    a: "He rubs the back of one hand with the other, showing the dry skin, then looks at the viewer.",
    e: "Same kitchen: he holds the back of his left hand toward the viewer, rubbing it with the right thumb." },
  { id: "s2_12e", k: "h", t: "Por eso la hidratación cambia tanto la cara. No toca la arruga profunda, pero sí todo lo que está alrededor.",
    a: "He makes a circle around his own face with one finger in the air and nods.",
    e: "Same kitchen: he draws a circle in the air around his face with one finger, nodding." },
  { id: "s2_12f", k: "d", t: "¿Liso o crespo? Da igual. Yo uso el liso porque se lava más fácil. Que esté verde oscuro y firme, sin hojas amarillas.",
    a: "Close-up: his hands lift a bunch of flat-leaf parsley next to a bunch of curly parsley on the counter, then pick one yellow leaf off and put it aside.",
    da: "Close-up of the white marble counter: a bunch of dark green flat-leaf parsley next to a bunch of curly parsley, his hand reaching for the flat-leaf one. Only hands visible.",
    db: "Same close-up: his hand holds up the flat-leaf bunch, the other hand has pinched off one yellowish leaf and holds it aside.",
    e: "Same kitchen, wide: he holds a fresh bunch of flat-leaf parsley over a tall glass with a little water, about to put it in like flowers." },
  { id: "s2_12g", k: "h", t: "Y el que te sobra, lo pones en un vaso con agua, como si fueran flores, dentro de la nevera. Así te dura una semana.",
    a: "He puts the parsley bunch standing in the tall glass of water like a bouquet and shows it to the viewer.",
    e: "Same kitchen: he holds the tall glass with the parsley standing in water like a bouquet, showing it to the viewer." },
  { id: "s2_13", k: "h", t: "Pero cómo se usa decide si te sirve o te hace daño. Y hay un detalle que casi nadie dice. Vamos al baño, te muestro.",
    a: "He becomes a bit more serious, raises a finger, then nods toward the hallway and steps sideways out from behind the counter.",
    e: "Same kitchen: he has stepped out from behind the counter toward the left, half turned toward the hallway, looking back at the viewer, beckoning with one hand." },
]},

{ id: "S3", lugar: "baño con espejo", base: "bathroom",
  k0: "A real, slightly lived-in home bathroom lit by a big frosted window: white tiled walls, a white sink with a chrome tap, a large mirror above it, a glass shelf with a toothbrush cup, a bar of soap, a jar of cotton pads, a small closed glass jar of light-green liquid and a folded white hand towel, a towel hanging on a ring, a potted plant on the windowsill. The doctor stands in front of the sink, turned three-quarters toward the viewer (his reflection visible in the mirror), looking at the viewer mid-sentence. Medium shot from the doorway, waist up, room around him.",
  lines: [
  { id: "s3_01", k: "h", t: "Te confieso algo. Esto yo lo hago de noche, siempre de noche. Ahora es de día porque si no, en la cámara no se ve nada.",
    a: "He leans a hip against the sink, smiles a little embarrassed, and gestures at the bright window.",
    e: "Same bathroom: he leans against the sink with a slightly embarrassed smile, one hand gesturing toward the bright frosted window." },
  { id: "s3_02", k: "h", t: "Y ya vas a entender por qué de noche. Pero antes de ponértelo en la cara, la primera vez, la prueba del parche.",
    a: "He picks up a cotton pad from the jar on the shelf and the small jar of green parsley water, showing both.",
    e: "Same bathroom: he holds a white cotton pad in one hand and the small glass jar of green parsley water in the other, showing them to the viewer." },
  { id: "s3_03", k: "d", t: "Mojas un algodón y te pones un poquito aquí, en la parte de adentro del brazo. O detrás de la oreja.",
    a: "Close-up: he dabs the wet cotton pad on the pale inner side of his forearm, twice, gently.",
    da: "Close-up of his left forearm turned up, pale inner skin, blue scrub sleeve pushed up, black smartwatch; his right hand holds a damp white cotton pad just above the inner forearm. Bathroom sink out of focus behind. Only arm and hands visible.",
    db: "Same close-up: the cotton pad is pressed on the inner forearm, the skin slightly wet and shiny where it touched.",
    e: "Same bathroom, medium shot as before: he holds up his left forearm with the inner side toward the viewer, pointing at the damp spot with the cotton pad." },
  { id: "s3_04", k: "h", t: "Esperas veinticuatro horas. Si se pone rojo, si pica, si arde, no lo usas en la cara. Y listo, no pasa nada, hay otras cosas.",
    a: "He lowers the arm, counts the three warning signs on his fingers and then shrugs calmly.",
    e: "Same bathroom: he stands with a relaxed shrug, palms up, calm reassuring face." },
  { id: "s3_05", k: "h", t: "Si no pasó nada, entonces sí. La cara limpia primero. Con agua tibia, eh, no caliente.",
    a: "He turns to the sink, opens the tap, tests the water with his fingers and bends to splash his face with both hands.",
    e: "Same bathroom: he is bent slightly over the sink with water on his face and hands, turning his wet face toward the viewer." },
  { id: "s3_06", k: "h", t: "El agua muy caliente reseca, y deshace justo lo que después le vas a poner. Es un error que veo todo el tiempo.",
    a: "He straightens up with a wet face, shakes his head at the tap, and turns the hot tap off decisively.",
    e: "Same bathroom: he stands straight with a wet face, one hand on the tap, looking at the viewer with a small frown of warning." },
  { id: "s3_07", k: "h", t: "Secas suave, sin frotar, a toquecitos con la toalla. Así.",
    a: "He takes the folded hand towel and pats his face dry with small gentle dabs, without rubbing.",
    e: "Same bathroom: he holds the white hand towel pressed gently against his cheek, eyes on the viewer, face now dry." },
  { id: "s3_08", k: "d", t: "Ahora el agua de perejil, fría de la nevera. Mojas un algodón, que quede húmedo pero que no chorree.",
    a: "Close-up: he tilts the small glass jar and wets a cotton pad with the light-green parsley water, then squeezes it lightly.",
    da: "Close-up over the white sink: his hand holds the small glass jar of light-green parsley water tilted toward a white cotton pad held in the other hand. Only hands visible.",
    db: "Same close-up: the cotton pad is now damp and pale green, his fingers squeezing it lightly, one drop falling into the sink.",
    e: "Same bathroom, medium shot facing the mirror three-quarters: he raises the damp green cotton pad toward his lower cheek, looking at his reflection." },
  { id: "s3_09", k: "h", t: "Y lo pasas por la cara de abajo hacia arriba. Mejillas, frente, el mentón. Suavecito, sin tironear la piel.",
    a: "Looking in the mirror, he sweeps the cotton pad upward over his cheek, then his forehead, then his chin, gently.",
    e: "Same bathroom: he is sweeping the cotton pad upward on his forehead, looking at his reflection, then his eyes move to the viewer." },
  { id: "s3_10", k: "h", t: "Los ojos, lejos. Ni el párpado ni justo debajo. Ahí la piel es muy finita y no es el lugar.",
    a: "He lowers the pad, points with his free index finger around his own eye without touching it, and shakes his head.",
    e: "Same bathroom: he points near (not touching) his own eye with his index finger, shaking his head slightly, the cotton pad lowered." },
  { id: "s3_11", k: "h", t: "Y no te olvides del cuello. El cuello es lo que más delata la edad, y nadie se lo trata. También de abajo hacia arriba.",
    a: "He lifts his chin a little and sweeps the cotton pad upward along the side of his neck several times.",
    e: "Same bathroom: chin slightly lifted, he sweeps the green cotton pad upward on the side of his neck, eyes toward the viewer." },
  { id: "s3_12", k: "h", t: "Y no lo enjuagas. Lo dejas secar solo, un minuto, y a dormir. Si usas tu crema de noche, va después, encima.",
    a: "He drops the cotton pad in a small bin, waves a hand near his face as if letting it dry, and picks up a plain white cream jar from the shelf.",
    e: "Same bathroom: he holds a plain white cream jar without label in one hand, face slightly damp, relaxed." },
  { id: "s3_12b", k: "d", t: "Un truco para no olvidarte: los algodones, al lado del cepillo de dientes. Los ves cada noche y te acuerdas.",
    a: "Close-up: his hand moves the jar of cotton pads on the glass shelf right next to the toothbrush cup and taps its lid.",
    da: "Close-up of the glass shelf above the sink: a jar of white cotton pads a little apart from a cup with toothbrushes, his hand reaching for the jar.",
    db: "Same close-up: the jar of cotton pads now stands right next to the toothbrush cup, his finger tapping its lid.",
    e: "Same bathroom, medium shot: he stands by the sink with his arms relaxed, looking at the viewer." },
  { id: "s3_12c", k: "h", t: "¿Y si una noche te olvidas? No pasa nada. Lo que cuenta son las semanas, no una noche suelta.",
    a: "He shrugs with a kind smile and waves a hand as if it doesn't matter.",
    e: "Same bathroom: he shrugs with a kind smile, one hand waving lightly." },
  { id: "s3_13", k: "h", t: "Ahora sí, el porqué de la noche. El perejil tiene unas sustancias que se llaman furanocumarinas. Una palabra fea, ya sé.",
    a: "He puts the cream jar down, turns fully to the viewer, and pronounces the long word with an amused grimace.",
    e: "Same bathroom: he faces the viewer fully with an amused grimace, hands together in front of him." },
  { id: "s3_14", k: "h", t: "Con el sol, esas sustancias pueden irritar la piel o dejar manchas. Por eso de noche, y a la mañana lavas la cara antes de salir.",
    a: "He points at the bright window with a serious face, then mimes washing his face with both hands.",
    e: "Same bathroom: he points at the bright frosted window with a serious face." },
  { id: "s3_15", k: "h", t: "Nada de ponértelo y salir al jardín, ¿eh? Ese es el error número uno. El que lo arruina todo.",
    a: "He wags his finger at the viewer, holds up one finger for 'number one', and nods firmly.",
    e: "Same bathroom: he holds up one index finger toward the viewer ('number one'), firm but kind face." },
  { id: "s3_16", k: "h", t: "Y a la mañana, si vas a salir, protector solar. Con o sin perejil. Eso no se negocia, a ninguna edad.",
    a: "He takes a plain white sunscreen tube without label from the shelf and shows it, nodding firmly.",
    e: "Same bathroom: he holds a plain white tube without label toward the viewer, nodding firmly." },
]},

{ id: "S4", lugar: "cocina con Carmen", base: "kitchen2",
  k0: "Same kitchen photo, later in the day: the counter now has the wooden cutting board with a fresh bunch of flat-leaf parsley, a small white bowl, a small plain white cup of natural yogurt with a spoon, and a small hand blender cup. He stands behind the counter as before, looking to the left side of the frame toward the hallway with a welcoming smile, as if someone just arrived. Everything else identical — do NOT add any book or aloe.",
  lines: [
  { id: "s4_01", k: "h", t: "Ah, mira quién llegó. Te dije que la paciente de la que te hablé me venía a visitar. Pasa, Carmen, pasa.",
    a: "He looks toward the left edge of the frame, smiles widely and waves someone in with his hand; the elderly woman from the fourth reference image walks in from the left and stops at the left end of the counter.",
    e: "Same kitchen: the elderly woman (exactly the woman in the last reference image: short soft white-grey hair, lilac knitted cardigan over a white blouse, 70 years old) now stands at the left end of the counter next to him, both smiling; he gestures toward her with an open hand.",
    refs: ["W"] },
  { id: "s4_02", k: "w", t: "¡Hola, doctor! Hola a todos. Yo soy Carmen, tengo setenta años, y sí, yo soy la de la cara.",
    a: "The elderly woman waves at the viewer, laughs, and points at her own face with both index fingers; the doctor laughs silently beside her.",
    e: "Same kitchen: the elderly woman points at her own face with both index fingers, laughing; the doctor beside her laughs silently, looking at her.",
    refs: ["W"] },
  { id: "s4_03", k: "h", t: "Carmen lleva... ¿cuánto? Casi dos meses con el agua de perejil. Cuéntales tú, que a mí no me van a creer.",
    a: "He turns to her, hesitates counting on his fingers, then opens his hand toward her inviting her to speak; she listens smiling and nods.",
    e: "Same kitchen: he holds an open hand toward the elderly woman inviting her to talk; she smiles at the viewer, ready to speak.",
    refs: ["W"] },
  { id: "s4_04", k: "w", t: "Mire, le voy a decir la verdad. Las arrugas siguen ahí, eh. Las de la frente siguen. No le voy a mentir a nadie.",
    a: "The elderly woman talks to the viewer, frank, touching the lines on her own forehead with one finger; the doctor listens silently and nods.",
    e: "Same kitchen: the elderly woman touches the lines on her forehead with one finger, frank expression; the doctor listens, nodding.",
    refs: ["W"] },
  { id: "s4_05", k: "w", t: "Pero ya no tengo la cara cansada. Y la semana pasada, en la farmacia, me pidieron la credencial para el descuento. ¡Me la pidieron!",
    a: "The elderly woman tells it with growing delight, pretends to hand over a card, and laughs at the end with her hand on her chest; the doctor laughs silently.",
    e: "Same kitchen: the elderly woman laughs with one hand on her chest; the doctor laughs silently beside her.",
    refs: ["W"] },
  { id: "s4_06", k: "h", t: "Y eso es lo que te decía al principio. No es que desapareció la arruga. Desapareció la cara de cansada, que es lo que más avejenta.",
    a: "Still smiling, he turns to the viewer and explains, pointing gently toward her cheek without touching it; she listens, nodding.",
    e: "Same kitchen: he explains to the viewer with an open hand; the elderly woman beside him nods, listening.",
    refs: ["W"] },
  { id: "s4_07", k: "h", t: "Cuando la piel está hidratada y con luz, las arrugas finitas se ven menos. Las profundas no, y no te voy a decir que sí.",
    a: "He explains calmly, making a small 'little' gesture with thumb and finger, then shakes his head honestly; she listens.",
    e: "Same kitchen: he shakes his head honestly with a small sincere smile; the elderly woman listens beside him.",
    refs: ["W"] },
  { id: "s4_08", k: "w", t: "Y yo me lo pongo de noche, como usted dijo, nunca de día. El frasco lo hago cada tres días, y lo tengo en la nevera junto a la leche.",
    a: "The elderly woman talks to the viewer, miming dabbing a cotton pad on her cheek and then pointing toward the fridge; the doctor listens silently.",
    e: "Same kitchen: the elderly woman points toward the fridge at the side of the kitchen, smiling; the doctor listens.",
    refs: ["W"] },
  { id: "s4_08b", k: "w", t: "Y mis hijas me preguntan qué me hice. Y yo les digo: ¡perejil! Y no me creen, doctor, no me creen.",
    a: "The elderly woman tells it laughing and shaking her head, hands open; the doctor listens silently, amused.",
    e: "Same kitchen: the elderly woman shakes her head laughing with open hands; the doctor beside her smiles.",
    refs: ["W"] },
  { id: "s4_08c", k: "h", t: "Y ese es el punto. No te vas a ver de cuarenta. Te vas a ver tú, pero descansada. Esa distancia es más corta de lo que crees.",
    a: "He turns to the viewer and speaks warmly, one hand gesturing toward her; she smiles and nods.",
    e: "Same kitchen: he speaks warmly to the viewer with a hand gesturing toward her; she nods beside him.",
    refs: ["W"] },
  { id: "s4_09", k: "h", t: "Perfecto. Y Carmen hace algo más, dos veces por semana. Una mascarilla. ¿Me ayudas a prepararla?",
    a: "He nods, pulls the cutting board with the parsley toward him and looks at her with a playful question; she laughs.",
    e: "Same kitchen: he has the cutting board with parsley right in front of him and the knife in hand, looking at the elderly woman with a playful question.",
    refs: ["W"] },
  { id: "s4_10", k: "w", t: "¡Claro que sí! Pero usted pica, que yo con el cuchillo soy un peligro.",
    a: "The elderly woman laughs and raises both hands in mock surrender, stepping back a little; the doctor laughs silently.",
    e: "Same kitchen: the elderly woman has both hands raised in mock surrender, laughing; the doctor holds the knife over the parsley, laughing silently.",
    refs: ["W"] },
  { id: "s4_11", k: "d", t: "Para la mascarilla, dos cucharadas de perejil fresco, picado muy finito, casi una pasta.",
    a: "Close-up: the knife chops the parsley very finely on the board, over and over, until it is almost a paste.",
    da: "Close-up of the wooden cutting board: a small pile of washed flat-leaf parsley and his hands with the kitchen knife starting to chop finely. Only hands visible.",
    db: "Same close-up: the parsley is now minced very finely, almost a dark green paste, gathered with the flat of the knife.",
    e: "Same kitchen, wide: the minced parsley is now in the small white bowl; he holds the little cup of natural yogurt and a spoon; the elderly woman watches beside him.",
    refs: ["W"] },
  { id: "s4_12", k: "h", t: "Y le agregas una cucharada de yogur natural. Natural, eh, sin azúcar, sin sabor a fresa, nada de eso.",
    a: "He spoons one spoonful of white natural yogurt into the bowl with the minced parsley, showing the spoon first; she nods.",
    e: "Same kitchen: he holds the empty spoon up after adding the yogurt to the bowl; the elderly woman looks into the bowl.",
    refs: ["W"] },
  { id: "s4_13", k: "d", t: "Mezclas hasta que quede una crema verde clarita. No es solo perejil, es verdad, lleva el yogur. Pero es lo único.",
    a: "Close-up: the spoon stirs the minced parsley into the white yogurt in the small white bowl until it becomes a smooth pale-green cream.",
    da: "Close-up of the small white bowl on the marble counter: a spoonful of white yogurt on top of minced green parsley, a spoon starting to stir. Only his hand visible.",
    db: "Same close-up: the mixture is now a smooth, even pale-green cream in the bowl, the spoon resting inside.",
    e: "Same kitchen, wide: he holds the small white bowl with the pale-green cream toward the viewer to show it; the elderly woman beside him looks at it.",
    refs: ["W"] },
  { id: "s4_14", k: "h", t: "Se pone con la cara limpia, igual que el agua, lejos de los ojos. Diez minutos, quince como mucho. Y se quita con agua tibia.",
    a: "He puts the bowl down and mimes spreading the mask on his cheeks with two fingers, then mimes rinsing; she listens.",
    e: "Same kitchen: he mimes spreading a mask on his cheek with two fingers; the elderly woman watches, nodding.",
    refs: ["W"] },
  { id: "s4_15", k: "h", t: "Dos veces por semana. No todos los días, que la piel también necesita descansar.",
    a: "He shows two fingers to the viewer, then waves a finger 'no, not every day'.",
    e: "Same kitchen: he holds up two fingers toward the viewer; the elderly woman beside him also holds up two fingers, smiling.",
    refs: ["W"] },
  { id: "s4_16", k: "h", t: "Y ahora, el otro error. El que hace que mucha gente diga: yo lo probé y no me sirvió.",
    a: "He becomes serious, leans on the counter toward the viewer; she stays silent and attentive.",
    e: "Same kitchen: he leans on the counter toward the viewer, serious; the elderly woman stands attentive beside him.",
    refs: ["W"] },
  { id: "s4_17", k: "h", t: "Le ponen limón. O vinagre, o bicarbonato. Porque lo vieron en internet. Y eso en la cara irrita, y con sol mancha.",
    a: "He picks up a lemon from the fruit bowl, shows it and shakes his head, puts it back firmly.",
    e: "Same kitchen: he holds a yellow lemon up in one hand and shakes his head with a disapproving face; the elderly woman grimaces.",
    refs: ["W"] },
  { id: "s4_18", k: "w", t: "Yo al principio le ponía limón, doctor. Y me puse colorada como un tomate.",
    a: "The elderly woman confesses laughing, covering her cheeks with both hands; the doctor puts the lemon back in the bowl and laughs silently.",
    e: "Same kitchen: the elderly woman covers her cheeks with both hands, laughing; the doctor beside her smiles and points at her.",
    refs: ["W"] },
  { id: "s4_19", k: "h", t: "¿Ves? Por eso lo digo. Nada de limón, ni bicarbonato, ni aceites esenciales puros en la cara. Gracias, Carmen, de verdad.",
    a: "He points at her, then counts the three no's on his fingers to the viewer, and finally hugs her briefly by the shoulder; she smiles and waves goodbye to the viewer.",
    e: "Same kitchen: he has an arm around the elderly woman's shoulder for a brief friendly hug, both smiling at the viewer, she waves goodbye.",
    refs: ["W"] },
]},

{ id: "S5", lugar: "living / escritorio", base: "living",
  k0: "A bright, lived-in home living room with a small wooden desk by a big window with sheer white curtains: on the desk a stack of papers, a mug of pens, reading glasses, a small potted plant and one single printed page lying face down; a bookshelf with books and framed family photos behind, a grey armchair with a knitted blanket. The doctor stands by the desk, looking at the viewer mid-sentence. Medium shot, waist up, room around him.",
  lines: [
  { id: "s5_01", k: "h", t: "Bueno, ya se fue Carmen. Y ahora quiero que veas esto, que es lo que más me importa del video.",
    a: "He walks to the desk, picks up the single printed page from the desk, still face down, and turns to the viewer.",
    e: "Same living room: he holds the single printed page against his chest with the blank back facing the viewer, looking at the viewer seriously." },
  { id: "s5_02", k: "h", t: "Presten mucha atención a esta imagen. Es la parte más importante del video.",
    a: "He slowly turns the page around and holds it up toward the viewer with both hands, serious, as if presenting it.",
    e: "Same living room: he holds up the printed page with both hands toward the viewer at chest height (a cream page with a green title, numbered boxes and a small diagram of a face, seen at an angle so no text is readable), serious face." },
  { id: "LAM", k: "lam", t: "Arriba, la receta: un puñado de perejil, veinte gramos, y doscientos cincuenta mililitros de agua recién hervida. Diez minutos tapado, colar, enfriar, y a la nevera en un frasco de vidrio, tres días. Al medio: de noche, con un algodón, de abajo hacia arriba, cara y cuello, lejos de los ojos, y sin enjuagar. Dos veces por semana, la mascarilla, con una cucharada de yogur natural. En el recuadro, los tres errores: el sol, el limón, y saltarse el parche. Y abajo, el plazo: tres a cuatro semanas. Sácale una foto a esta hoja." },
  { id: "s5_03", k: "h", t: "Y dicho sea de paso, esta hoja la hice igual que las páginas de mi guía completa. El perejil no está en la guía, eh: esto es de aquí.",
    a: "Back in the living room, he lowers the page to his side casually and talks to the viewer relaxed, one hand in his pocket.",
    e: "Same living room: he stands relaxed with the page lowered at his side and one hand in his pocket, friendly face.",
    same_start_as: "s5_02" },
  { id: "s5_04", k: "h", t: "La guía es para la firmeza: qué comer para el colágeno, la rutina de noche en tres pasos, y el cuello.",
    a: "He counts three things on his fingers while he talks, casual.",
    e: "Same living room: he holds up three fingers, casual smile." },
  { id: "s5_05", k: "h", t: "Si están viendo en el televisor, escaneen el código; si están en el teléfono, el enlace está abajo.",
    a: "He points toward the side of the frame as if at a code on screen, then points down toward the bottom of the frame.",
    e: "Same living room: he points down toward the bottom of the frame with his index finger, smiling." },
  { id: "s5_06", k: "h", t: "Pero lo de hoy ya lo tienes entero. Y me falta la otra mitad: lo que pasa cuando el perejil, en vez de ponértelo, te lo comes.",
    a: "He puts the page back on the desk, raises an eyebrow with a curious smile and starts walking out toward the kitchen.",
    e: "Same living room: he has turned toward the door on the side, looking back at the viewer with a curious raised eyebrow and a half smile." },
]},

{ id: "S6", lugar: "cocina (comerlo + advertencias)", base: "kitchen3",
  k0: "Same kitchen photo, at lunchtime: on the counter a bowl of hot vegetable soup, a plate with scrambled eggs on toast, a bowl of green salad, the cutting board with a small pile of freshly chopped flat-leaf parsley, a glass of water. He stands behind the counter holding a pinch of chopped parsley over the soup, looking at the viewer. Everything else identical — do NOT add any book or aloe.",
  lines: [
  { id: "s6_01", k: "h", t: "Porque la piel se arma desde adentro. Y el perejil fresco, comido, es de las fuentes más baratas de vitamina C que hay.",
    a: "He sprinkles the pinch of chopped parsley over the soup and looks up at the viewer while talking.",
    e: "Same kitchen: he has sprinkled chopped parsley over the soup and holds the spoon, looking at the viewer." },
  { id: "s6_02", k: "d", t: "Dos cucharadas picadas al día. Arriba de la sopa, en la ensalada, en los huevos revueltos. Crudo, al final.",
    a: "Close-up: his fingers sprinkle chopped fresh parsley over scrambled eggs on toast, then over a green salad.",
    da: "Close-up of a plate with scrambled eggs on toast on the marble counter, his fingers holding a pinch of chopped fresh parsley just above it. Only hand visible.",
    db: "Same close-up: bright green chopped parsley now scattered over the scrambled eggs, his fingers moving away.",
    e: "Same kitchen, wide: he takes a bite of the scrambled eggs with parsley with a fork, chewing, amused, looking at the viewer." },
  { id: "s6_03", k: "h", t: "Crudo, porque el calor le quita buena parte de la vitamina C. Si lo hierves media hora en el guiso, ya no es lo mismo.",
    a: "He swallows, points the fork at the viewer, and mimes a pot boiling with his other hand, shaking his head.",
    e: "Same kitchen: he points the fork toward the viewer, shaking his head with a small smile." },
  { id: "s6_04", k: "h", t: "Y otra cosa: el colágeno se hace con proteína. Si comes poca, y después de los sesenta pasa mucho, el perejil solo no alcanza.",
    a: "He puts the fork down and raises an index finger, then taps the plate of eggs.",
    e: "Same kitchen: he taps the rim of the plate of eggs with one finger, explaining." },
  { id: "s6_05", k: "h", t: "Un huevo, un poco de pollo, lentejas, un yogur. Eso, junto con el perejil. No es magia, es materia prima.",
    a: "He points one by one at the eggs, the soup and the yogurt cup, then opens both hands.",
    e: "Same kitchen: he opens both hands over the food on the counter, a practical smile." },
  { id: "s6_05b", k: "d", t: "Otra forma que me gusta: una salsa verde, con aceite de oliva, un diente de ajo y mucho perejil. Arriba del pescado, de la carne.",
    a: "Close-up: a spoon drizzles a rustic green parsley and olive-oil sauce over a piece of grilled white fish on a plate.",
    da: "Close-up of a plate with a piece of grilled white fish on the marble counter, a small glass bowl of green parsley sauce with olive oil beside it, his hand holding a spoon full of the sauce above the fish.",
    db: "Same close-up: the green parsley sauce is drizzled over the fish, shiny olive oil, the spoon moving away.",
    e: "Same kitchen, wide: he holds the small glass bowl of green parsley sauce, smiling at the viewer." },
  { id: "s6_05c", k: "h", t: "Y la vitamina C el cuerpo no la guarda. Por eso es mejor un poquito todos los días, que mucho un día solo.",
    a: "He puts the bowl down and taps the counter rhythmically with his finger as if counting days.",
    e: "Same kitchen: he taps the counter with one finger, counting days, explaining." },
  { id: "s6_05d", k: "h", t: "¿Y en el jugo verde de la mañana? Un puñadito está bien. Un puñadito, eh, no el atado entero.",
    a: "He shows a small pinch of parsley with his fingers, then pretends to hold a whole bunch and shakes his head, laughing.",
    e: "Same kitchen: he holds up a small pinch of parsley between his fingers, laughing." },
  { id: "s6_06", k: "h", t: "Ahora, las advertencias. Y te pido que no te las saltes, porque son importantes.",
    a: "He wipes his hands on a kitchen towel, puts it down and leans on the counter, serious.",
    e: "Same kitchen: he leans with both hands on the counter, serious, looking straight at the viewer." },
  { id: "s6_07", k: "h", t: "El perejil tiene mucha vitamina K. Si tomas anticoagulantes, como la warfarina, comer mucho de golpe puede cambiar el efecto del remedio.",
    a: "He speaks slowly and clearly, holding up the small bunch of parsley in one hand as he talks.",
    e: "Same kitchen: he holds up the small parsley bunch, serious caring face." },
  { id: "s6_08", k: "h", t: "No quiere decir que no puedas comerlo. Quiere decir que lo hables con tu médico antes, y que no cambies la cantidad de un día para otro.",
    a: "He puts the parsley down, makes a calming gesture with his palm, and nods.",
    e: "Same kitchen: he makes a calming gesture with one open palm, reassuring face." },
  { id: "s6_09", k: "h", t: "Si tienes problemas de riñón, también consulta primero. Y en el embarazo, grandes cantidades de perejil no se recomiendan.",
    a: "He counts two more warnings on his fingers, calm and clear.",
    e: "Same kitchen: he holds up two fingers, calm and clear." },
  { id: "s6_10", k: "h", t: "Una ramita en la ensalada no es el problema. El problema es tomarse litros de jugo de perejil porque alguien dijo que desintoxica.",
    a: "He picks a single sprig and drops it on the salad with a relaxed smile, then mimes drinking a huge glass with an ironic face.",
    e: "Same kitchen: he mimes drinking from a huge imaginary glass with an ironic raised eyebrow." },
  { id: "s6_11", k: "h", t: "Y en la piel, ya lo dijimos: prueba del parche, de noche, sin sol, lejos de los ojos. Con eso estás cuidada.",
    a: "He counts the four rules on his fingers, smiling warmly at the end.",
    e: "Same kitchen: he smiles warmly with four fingers up, then relaxed." },
]},

{ id: "S7", lugar: "baño, espejo (qué esperar)", base: "bathroom2",
  k0: "Same bathroom photo as the reference: the doctor stands in front of the mirror looking closely at his own face in the reflection, one hand touching his cheek, then turned slightly toward the viewer. Everything else identical.",
  lines: [
  { id: "s7_01", k: "h", t: "Bueno, ahora lo que todos quieren saber. ¿Qué vas a ver en el espejo, y cuándo? Te lo digo como es.",
    a: "He looks at his reflection, touches his cheek, then turns to the viewer and speaks directly.",
    e: "Same bathroom: he has turned from the mirror toward the viewer, one hand still near his cheek, honest face." },
  { id: "s7_02", k: "h", t: "La primera semana, casi nada. Quizás la piel un poco más fresca por la mañana. Nada más. No te desanimes.",
    a: "He makes a 'tiny' gesture with thumb and index finger, then an encouraging nod.",
    e: "Same bathroom: he shows a tiny gap between thumb and index finger, encouraging smile." },
  { id: "s7_03", k: "h", t: "A las tres o cuatro semanas, si lo hiciste todas las noches, la piel se ve más luminosa, más pareja, más hidratada.",
    a: "He counts weeks on his fingers and then gestures softly around his own face.",
    e: "Same bathroom: his open hand hovers softly near his face, satisfied expression." },
  { id: "s7_04", k: "h", t: "Las arrugas finitas, las de la sequedad, se suavizan a la vista. Las profundas, las del ceño, las de treinta años, esas no se van.",
    a: "He points at fine lines near his eye corner, then at the frown line between his brows, shaking his head.",
    e: "Same bathroom: he points at the frown line between his own brows, shaking his head honestly." },
  { id: "s7_05", k: "h", t: "Y si alguien te dice que en siete días se te borran, desconfía. Yo prefiero decirte la verdad y que vuelvas.",
    a: "He wags a finger with a skeptical face, then puts his hand on his chest, sincere.",
    e: "Same bathroom: his hand is on his chest, sincere face." },
  { id: "s7_06", k: "h", t: "Lo que sí cambia, y mucho, es la cara de cansada. Eso que te hace ver mayor de lo que eres. Eso es lo que notó Carmen.",
    a: "He smiles, gestures at his own face and then nods toward the door, remembering Carmen.",
    e: "Same bathroom: he smiles warmly, nodding toward the door." },
  { id: "s7_07", k: "d", t: "Un consejo: sácate una foto hoy, con la luz de la ventana. Y otra dentro de cuatro semanas, con la misma luz.",
    a: "Close-up: his hand holds a smartphone up by the bright frosted window, back of the phone toward the viewer, as if taking a selfie; small adjustment of the angle.",
    da: "Close-up by the bright frosted bathroom window: his hand holds a black smartphone up, the BACK of the phone toward the viewer (no screen visible), the window light on his fingers and wrist with the black smartwatch.",
    db: "Same close-up: the phone slightly rotated, his thumb pressing the side, the back of the phone still toward the viewer.",
    e: "Same bathroom, medium shot: he lowers the phone, back toward the viewer, and looks at the viewer with a small smile." },
  { id: "s7_08", k: "h", t: "Porque uno se ve todos los días y no nota el cambio. En la foto sí se nota. O no se nota, y también está bien saberlo.",
    a: "He puts the phone face down on the shelf and shrugs honestly.",
    e: "Same bathroom: he shrugs honestly, the phone face down on the glass shelf." },
  { id: "s7_09", k: "h", t: "Y si en un mes no ves nada, no pasa nada. No todas las pieles responden igual. Al menos no gastaste en una crema de ochenta dólares.",
    a: "He smiles, taps the small jar of green parsley water on the shelf and laughs briefly.",
    e: "Same bathroom: he taps the small glass jar of green parsley water on the shelf, laughing briefly." },
  { id: "s7_09b", k: "h", t: "¿Y cuánto tiempo hay que hacerlo? El que quieras. Pero si lo dejas, la piel vuelve a como estaba. No queda fijo.",
    a: "He tilts his head at an imaginary question, then opens his hands honestly.",
    e: "Same bathroom: he opens both hands honestly toward the viewer." },
  { id: "s7_09c", k: "h", t: "Porque esto cuida la hidratación de todos los días. No es una cirugía, es un hábito. Como lavarse los dientes.",
    a: "He picks up his toothbrush from the cup, shows it with a smile, and puts it back.",
    e: "Same bathroom: he puts the toothbrush back in the cup, smiling at the viewer." },
  { id: "s7_10", k: "h", t: "¿Y me preguntan si sirve el perejil seco, el de frasquito? Para esto, no. Tiene que ser fresco, verde, firme.",
    a: "He shakes his head to an imaginary question, pretends to hold a small spice jar with disdain, then mimes a fresh bunch.",
    e: "Same bathroom: he shakes his head with a small smile, one hand as if holding a fresh bunch." },
  { id: "s7_11", k: "h", t: "¿Y para las manchas? Algo de luminosidad da. Pero para las manchas, lo que más importa es el protector solar de día. Siempre.",
    a: "He thinks, tilts his head, and then points toward the bright window with emphasis.",
    e: "Same bathroom: he points toward the bright window with emphasis, serious." },
  { id: "s7_12", k: "h", t: "¿Y los hombres? También, claro. La piel es piel. Yo mismo lo uso algunas noches, no te voy a mentir.",
    a: "He laughs, points at himself, and gives a small embarrassed smile.",
    e: "Same bathroom: he points at himself with a small embarrassed smile." },
  { id: "s7_13", k: "h", t: "Y si tienes la piel muy sensible, o rosácea, prueba del parche con más cuidado. Si arde, no. No hay que aguantar nada.",
    a: "He speaks carefully, touches his inner forearm where he did the patch test, and shakes his head firmly.",
    e: "Same bathroom: he touches his inner forearm, shaking his head firmly but kindly." },
]},

{ id: "S8", lugar: "patio (cierre)", base: "patio2",
  k0: "Same patio photo as the reference, late afternoon but still bright daylight: the doctor stands next to the big clay pot of parsley (with some stems freshly cut), holding a watering can, looking at the viewer. Everything else identical.",
  lines: [
  { id: "s8_01", k: "h", t: "Y bueno, aquí volvemos, al principio. Al perejil. Que cuesta casi nada y lo tienes en cualquier verdulería.",
    a: "He waters the parsley pot a little, puts the watering can down and looks at the viewer.",
    e: "Same patio: he has put the watering can down on the bench and stands next to the pot, relaxed, looking at the viewer." },
  { id: "s8_02", k: "h", t: "Si lo quieres tener en casa, una maceta así, con sol de la mañana y riego seguido, y cortas de afuera hacia adentro.",
    a: "He touches the outer stems of the pot showing where to cut, then glances up at the sun.",
    e: "Same patio: he points at the outer stems of the parsley pot, explaining." },
  { id: "s8_02b", k: "d", t: "Y compra un plantín, no semillas, que tardan muchísimo en salir. Un plantín, y en dos semanas ya estás cortando.",
    a: "Close-up: his hands press soil around a small parsley seedling in a new clay pot, then give it a little water.",
    da: "Close-up of a small new clay pot on the wooden bench with dark soil and a young parsley seedling, his hands holding its small root ball, about to press it in.",
    db: "Same close-up: the seedling now firmly planted, his fingers pressing the soil around it, a few drops of water on the leaves.",
    e: "Same patio, wide: he stands next to the bench with the small new pot beside the big parsley pot, brushing soil off his hands, smiling at the viewer." },
  { id: "s8_02c", k: "h", t: "Y cuando florece, se pone amargo. Así que ve cortando seguido, que eso lo mantiene tierno.",
    a: "He cuts one stem from the big pot with his fingers, smells it, and nods.",
    e: "Same patio: he holds a freshly picked parsley stem near his nose, nodding." },
  { id: "s8_03", k: "h", t: "Te dejo la receta entera en el video, y la hoja para que le saques foto. La guía de la firmeza está abajo, para el que quiera más.",
    a: "He points at the camera, then down toward the bottom of the frame, casual.",
    e: "Same patio: he points down toward the bottom of the frame, casual smile." },
  { id: "s8_04", k: "h", t: "Y cuéntame en los comentarios cuántos años tienes y si lo vas a probar. Los leo todos, de verdad.",
    a: "He crouches next to the pot again, smiling, and mimes typing a comment with his thumbs.",
    e: "Same patio: he crouches next to the parsley pot, smiling warmly at the viewer." },
  { id: "s8_05", k: "h", t: "Nos vemos en el próximo. Y esta noche: algodón, perejil, y a dormir. Cuídate mucho.",
    a: "He picks one parsley leaf, holds it up with a wink, and waves goodbye to the viewer.",
    e: "Same patio: he waves goodbye to the viewer with a big smile, a parsley leaf in the other hand." },
]},
];
